#!/usr/bin/env python3
import os
import sys
import re
import json
import time
import subprocess
from dataclasses import dataclass, field
from datetime import date
from typing import List, Optional, Dict, Tuple, Any

VERSION = "0.10.0"

HELP_TEXT = """a conventional changelog for the rest of us

Usage: {prog} [OPTIONS]

Options:
  -r, --repository <URL>  Repository used for generating commit and issue links (without the .git,
                          e.g. https://github.com/thoughtram/clog)
  -f, --from <COMMIT>     e.g. 12a8546
  -T, --format <STR>      The output format, defaults to markdown [default: markdown] [possible
                          values: markdown, json]
  -M, --major             Increment major version by one (Sets minor and patch to 0)
  -g, --git-dir <PATH>    Local .git directory (defaults to "$(pwd)/.git")
  -w, --work-tree <PATH>  Local working tree of the git project (defaults to "$(pwd)")
  -m, --minor             Increment minor version by one (Sets patch to 0)
  -p, --patch             Increment patch version by one
  -s, --subtitle <STR>    
  -t, --to <COMMIT>       e.g. 8057684 [default: HEAD]
  -o, --outfile <PATH>    Where to write the changelog (Defaults to stdout when omitted)
  -c, --config <COMMIT>   The Clog Configuration TOML file to use [default: .clog.toml]
  -i, --infile <PATH>     A changelog to append to, but *NOT* write to (Useful in conjunction with
                          --outfile)
      --setversion <VER>  e.g. 1.0.1
  -F, --from-latest-tag   use latest tag as start (instead of --from)
  -l, --link-style <STR>  The style of repository link to generate [default: github] [possible
                          values: github, gitlab, stash, cgit]
  -C, --changelog <PATH>  A previous changelog to prepend new changes to (this is like using the
                          same file for both --infile and --outfile and should not be used in
                          conjunction with either)
  -h, --help              Print help
  -V, --version           Print version


If your .git directory is a child of your project directory (most common, such as /myproject/.git)
AND not in the current working directory (i.e you need to use --work-tree or --git-dir) you only
need to specify either the --work-tree (i.e. /myproject) OR --git-dir (i.e. /myproject/.git), you
don't need to use both.

If using the --config to specify a clog configuration TOML file NOT in the current working directory
(meaning you need to use --work-tree or --git-dir) AND the TOML file is inside your project
directory (i.e. /myproject/.clog.toml) you do not need to use --work-tree or --git-dir.
"""

VALUE_OPTS = {
    "repository": ("repository", "--repository <URL>"),
    "from": ("from_commit", "--from <COMMIT>"),
    "format": ("format", "--format <STR>"),
    "git-dir": ("git_dir", "--git-dir <PATH>"),
    "work-tree": ("work_tree", "--work-tree <PATH>"),
    "subtitle": ("subtitle", "--subtitle <STR>"),
    "to": ("to", "--to <COMMIT>"),
    "outfile": ("outfile", "--outfile <PATH>"),
    "config": ("config", "--config <COMMIT>"),
    "infile": ("infile", "--infile <PATH>"),
    "setversion": ("setversion", "--setversion <VER>"),
    "link-style": ("link_style", "--link-style <STR>"),
    "changelog": ("changelog", "--changelog <PATH>"),
}
SHORT_VALUE = {
    "r": "repository",
    "f": "from",
    "T": "format",
    "g": "git-dir",
    "w": "work-tree",
    "s": "subtitle",
    "t": "to",
    "o": "outfile",
    "c": "config",
    "i": "infile",
    "l": "link-style",
    "C": "changelog",
}
FLAG_OPTS = {
    "major": "major",
    "minor": "minor",
    "patch": "patch",
    "from-latest-tag": "from_latest_tag",
    "help": "help",
    "version": "version",
}
SHORT_FLAG = {
    "M": "major",
    "m": "minor",
    "p": "patch",
    "F": "from-latest-tag",
    "h": "help",
    "V": "version",
}
ENUMS = {
    "format": ["markdown", "json"],
    "link-style": ["github", "gitlab", "stash", "cgit"],
}

@dataclass
class Opts:
    repository: Optional[str] = None
    from_commit: Optional[str] = None
    format: str = "markdown"
    major: bool = False
    git_dir: Optional[str] = None
    work_tree: Optional[str] = None
    minor: bool = False
    patch: bool = False
    subtitle: Optional[str] = None
    to: str = "HEAD"
    outfile: Optional[str] = None
    config: str = ".clog.toml"
    infile: Optional[str] = None
    setversion: Optional[str] = None
    from_latest_tag: bool = False
    link_style: str = "github"
    changelog: Optional[str] = None
    cli_from: bool = False
    cli_from_latest: bool = False
    to_supplied: bool = False

class CliExit(Exception):
    def __init__(self, code: int):
        self.code = code

class CliError(Exception):
    pass

class TomlError(Exception):
    pass


def prog_name() -> str:
    return os.path.basename(sys.argv[0]) or "executable"


def print_help_and_exit():
    sys.stdout.write(HELP_TEXT.format(prog=prog_name()))
    raise CliExit(0)


def print_version_and_exit():
    sys.stdout.write(f"clog {VERSION}\n")
    raise CliExit(0)


def parser_error(msg: str):
    sys.stderr.write(msg)
    raise CliExit(2)


def app_error(msg: str):
    sys.stderr.write(f"\033[1;31merror:\033[0m {msg}\n")
    raise CliExit(1)


def usage_line(extra: str = "[OPTIONS]") -> str:
    return f"Usage: {prog_name()} {extra}\n"


def unexpected_arg(arg: str):
    parser_error(f"error: unexpected argument '{arg}' found\n\n{usage_line()}\nFor more information, try '--help'.\n")


def missing_value(longname: str):
    _attr, display = VALUE_OPTS[longname]
    add = ""
    if longname in ENUMS:
        add = "\n  [possible values: " + ", ".join(ENUMS[longname]) + "]"
    parser_error(f"error: a value is required for '{display}' but none was supplied{add}\n\nFor more information, try '--help'.\n")


def invalid_value(longname: str, val: str):
    _attr, display = VALUE_OPTS[longname]
    parser_error(
        f"error: invalid value '{val}' for '{display}'\n"
        f"  [possible values: {', '.join(ENUMS[longname])}]\n\n"
        "For more information, try '--help'.\n"
    )


def flag_unexpected_value(longname: str, val: str):
    parser_error(
        f"error: unexpected value '{val}' for '--{longname}' found; no more were expected\n\n"
        f"Usage: {prog_name()} --{longname}\n\n"
        "For more information, try '--help'.\n"
    )


def is_known_option_token(tok: str) -> bool:
    if tok == "--":
        return True
    if tok.startswith("--"):
        name = tok[2:].split("=", 1)[0]
        return name in VALUE_OPTS or name in FLAG_OPTS
    if tok.startswith("-") and tok != "-":
        ch = tok[1:2]
        return ch in SHORT_VALUE or ch in SHORT_FLAG
    return False


def set_value(opts: Opts, longname: str, val: str):
    if longname in ENUMS:
        if val == "":
            missing_value(longname)
        if val not in ENUMS[longname]:
            invalid_value(longname, val)
    attr, _display = VALUE_OPTS[longname]
    setattr(opts, attr, val)
    if longname == "from":
        opts.cli_from = True
    elif longname == "to":
        opts.to_supplied = True


def set_flag(opts: Opts, longname: str):
    if longname == "help":
        print_help_and_exit()
    if longname == "version":
        print_version_and_exit()
    attr = FLAG_OPTS[longname]
    setattr(opts, attr, True)
    if longname == "from-latest-tag":
        opts.cli_from_latest = True


def parse_args(argv: List[str]) -> Opts:
    opts = Opts()
    i = 0
    stop_options = False
    while i < len(argv):
        arg = argv[i]
        if stop_options:
            unexpected_arg(arg)
        if arg == "--":
            stop_options = True
            i += 1
            continue
        if arg.startswith("--") and arg != "--":
            body = arg[2:]
            if "=" in body:
                name, val = body.split("=", 1)
                if name in FLAG_OPTS:
                    flag_unexpected_value(name, val)
                if name not in VALUE_OPTS:
                    unexpected_arg(arg)
                set_value(opts, name, val)
                i += 1
                continue
            name = body
            if name in FLAG_OPTS:
                set_flag(opts, name)
                i += 1
                continue
            if name in VALUE_OPTS:
                if i + 1 >= len(argv):
                    missing_value(name)
                nxt = argv[i + 1]
                if nxt.startswith("-") and nxt != "-":
                    if is_known_option_token(nxt):
                        missing_value(name)
                    else:
                        unexpected_arg(nxt)
                set_value(opts, name, nxt)
                i += 2
                continue
            unexpected_arg(arg)
        elif arg.startswith("-") and arg != "-":
            # Short options can be grouped for flags; value options consume the rest
            # of the token or the following argument.
            j = 1
            while j < len(arg):
                ch = arg[j]
                if ch in SHORT_FLAG:
                    set_flag(opts, SHORT_FLAG[ch])
                    j += 1
                    continue
                if ch in SHORT_VALUE:
                    name = SHORT_VALUE[ch]
                    if j + 1 < len(arg):
                        val = arg[j + 1:]
                        set_value(opts, name, val)
                        j = len(arg)
                        break
                    if i + 1 >= len(argv):
                        missing_value(name)
                    nxt = argv[i + 1]
                    if nxt.startswith("-") and nxt != "-":
                        if is_known_option_token(nxt):
                            missing_value(name)
                        else:
                            unexpected_arg(nxt)
                    set_value(opts, name, nxt)
                    i += 1
                    j = len(arg)
                    break
                unexpected_arg("-" + ch if len(arg) == 2 else arg)
            i += 1
        else:
            unexpected_arg(arg)

    # Conflicts, matching the common clap wording used by this binary.
    if opts.cli_from and opts.cli_from_latest:
        extra = ""
        if opts.setversion is not None:
            extra += "--setversion <VER> "
        extra += "--from <COMMIT>"
        parser_error(
            "error: the argument '--from <COMMIT>' cannot be used with '--from-latest-tag'\n\n"
            f"Usage: {prog_name()} {extra}\n\n"
            "For more information, try '--help'.\n"
        )
    if opts.changelog and (opts.outfile or opts.infile):
        conflicts = []
        if opts.outfile:
            conflicts.append("--outfile <PATH>")
        if opts.infile:
            conflicts.append("--infile <PATH>")
        if len(conflicts) == 1:
            parser_error(
                f"error: the argument '--changelog <PATH>' cannot be used with '{conflicts[0]}'\n\n"
                f"Usage: {prog_name()} " + ("--setversion <VER> " if opts.setversion is not None else "") + "--changelog <PATH>\n\n"
                "For more information, try '--help'.\n"
            )
        else:
            parser_error(
                "error: the argument '--changelog <PATH>' cannot be used with:\n"
                "  --outfile <PATH>\n"
                "  --infile <PATH>\n\n"
                f"Usage: {prog_name()} " + ("--setversion <VER> " if opts.setversion is not None else "") + "--changelog <PATH>\n\n"
                "For more information, try '--help'.\n"
            )
    return opts


# A deliberately small TOML reader for the documented clog config surface.
def strip_comment(line: str) -> str:
    out = []
    in_str = False
    esc = False
    for c in line:
        if in_str:
            out.append(c)
            if esc:
                esc = False
            elif c == "\\":
                esc = True
            elif c == '"':
                in_str = False
        else:
            if c == '"':
                in_str = True
                out.append(c)
            elif c == '#':
                break
            else:
                out.append(c)
    if in_str:
        raise TomlError()
    return ''.join(out).strip()


def parse_string(s: str) -> str:
    if len(s) < 2 or not (s[0] == '"' and s[-1] == '"'):
        raise TomlError()
    body = s[1:-1]
    res = []
    i = 0
    while i < len(body):
        c = body[i]
        if c == "\\":
            i += 1
            if i >= len(body):
                raise TomlError()
            e = body[i]
            if e == 'n':
                res.append('\n')
            elif e == 't':
                res.append('\t')
            elif e == 'r':
                res.append('\r')
            elif e in ['"', "\\"]:
                res.append(e)
            else:
                # TOML has more escapes; preserve common unknowns rather than exploding.
                res.append(e)
        else:
            res.append(c)
        i += 1
    return ''.join(res)


def parse_key(s: str) -> str:
    s = s.strip()
    if not s:
        raise TomlError()
    if s.startswith('"'):
        return parse_string(s)
    if re.match(r'^[A-Za-z0-9_-]+$', s):
        return s
    raise TomlError()


def split_array_items(body: str) -> List[str]:
    items = []
    cur = []
    in_str = False
    esc = False
    for c in body:
        if in_str:
            cur.append(c)
            if esc:
                esc = False
            elif c == "\\":
                esc = True
            elif c == '"':
                in_str = False
        else:
            if c == '"':
                in_str = True
                cur.append(c)
            elif c == ',':
                item = ''.join(cur).strip()
                if item:
                    items.append(item)
                cur = []
            else:
                cur.append(c)
    if in_str:
        raise TomlError()
    item = ''.join(cur).strip()
    if item:
        items.append(item)
    return items


def parse_value(s: str) -> Any:
    s = s.strip()
    if s == 'true':
        return True
    if s == 'false':
        return False
    if s.startswith('"'):
        return parse_string(s)
    if s.startswith('['):
        if not s.endswith(']'):
            raise TomlError()
        inner = s[1:-1].strip()
        if not inner:
            return []
        return [parse_value(x) for x in split_array_items(inner)]
    # Accept simple numeric/bare values for unknown keys; malformed whitespace is rejected earlier.
    if re.match(r'^[+-]?[0-9]+(\.[0-9]+)?$', s):
        return s
    if re.match(r'^[A-Za-z0-9_./:+-]+$', s):
        return s
    raise TomlError()


def parse_toml(path: str) -> Tuple[List[Tuple[str, List[str]]], bool]:
    try:
        text = open(path, 'r', encoding='utf-8').read()
    except Exception:
        app_error("fatal I/O error with output file")
    current = ""
    data: Dict[str, Dict[str, Any]] = {"": {}}
    section_order: List[Tuple[str, List[str]]] = []
    try:
        for raw in text.splitlines():
            line = strip_comment(raw)
            if not line:
                continue
            if line.startswith('['):
                if not line.endswith(']'):
                    raise TomlError()
                table = line[1:-1].strip()
                # basic validation; dotted tables are otherwise kept as their literal names
                if not table or any(part.strip() == "" for part in table.split('.')):
                    raise TomlError()
                # This program's deserializer rejects subtables under [sections].
                if table.startswith('sections.'):
                    raise TomlError()
                current = table
                data.setdefault(current, {})
                continue
            if '=' not in line:
                raise TomlError()
            k, v = line.split('=', 1)
            key = parse_key(k)
            val = parse_value(v)
            data.setdefault(current, {})[key] = val
            if current == 'sections':
                if not isinstance(val, list) or any(not isinstance(x, str) for x in val):
                    raise TomlError()
                # Rust's TOML table iteration preserves the apparent order for this use.
                section_order.append((key, val))
        clog = data.get('clog', {})
        from_latest_config = False
        if 'from-latest-tag' in clog:
            if not isinstance(clog['from-latest-tag'], bool):
                raise TomlError()
            from_latest_config = bool(clog['from-latest-tag'])
        # Known [clog] string fields are type-checked by serde in the original.
        for k in ('repository', 'link-style', 'subtitle', 'changelog'):
            if k in clog and not isinstance(clog[k], str):
                raise TomlError()
        return section_order, from_latest_config
    except TomlError:
        app_error("Failed to parse TOML configuration file")


@dataclass
class Issue:
    issue: int
    issue_link: str

@dataclass
class CommitEntry:
    component: Optional[str]
    subject: str
    full_hash: str
    short_hash: str
    commit_link: str
    closes: List[Issue] = field(default_factory=list)
    break_entries: List[Optional[int]] = field(default_factory=list)  # one per BREAKING line; issue or None
    break_issues: List[Issue] = field(default_factory=list)

@dataclass
class SectionOut:
    title: str
    commits: List[CommitEntry]


def run_git(args: List[str], opts: Opts, base_dir: str) -> Optional[str]:
    cmd = ['git']
    if opts.git_dir:
        cmd += ['--git-dir', opts.git_dir]
        wt = opts.work_tree
        if not wt:
            gd = opts.git_dir
            if gd.endswith('/.git') or gd.endswith('\\.git') or os.path.basename(gd) == '.git':
                wt = os.path.dirname(os.path.abspath(gd))
            else:
                wt = base_dir
        if wt:
            cmd += ['--work-tree', wt]
    else:
        cmd += ['-C', base_dir]
    cmd += args
    try:
        p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True, check=False)
    except Exception:
        return None
    if p.returncode != 0:
        return None
    return p.stdout


def resolve_rev(rev: str, opts: Opts, base_dir: str) -> Optional[str]:
    out = run_git(['rev-parse', '--verify', f'{rev}^{{commit}}'], opts, base_dir)
    if out is None:
        return None
    val = out.strip().splitlines()[0] if out.strip() else None
    return val


def latest_tag(opts: Opts, base_dir: str) -> Optional[str]:
    out = run_git(['describe', '--tags', '--abbrev=0'], opts, base_dir)
    if out is None:
        return None
    tag = out.strip().splitlines()[0] if out.strip() else None
    return tag


def git_rev_list(range_args: List[str], opts: Opts, base_dir: str) -> List[str]:
    out = run_git(['rev-list'] + range_args, opts, base_dir)
    if out is None:
        return []
    return [x.strip() for x in out.splitlines() if x.strip()]


def get_message(h: str, opts: Opts, base_dir: str) -> str:
    out = run_git(['show', '-s', '--format=%B', h], opts, base_dir)
    return out if out is not None else ''


def infer_base_dir(opts: Opts, config_path: str) -> str:
    if opts.work_tree:
        return opts.work_tree
    # Explicit/default config, when it exists, is treated as a hint to the project tree.
    if os.path.isabs(config_path):
        return os.path.dirname(config_path)
    return os.path.dirname(os.path.abspath(config_path)) or os.getcwd()


def collect_hashes(opts: Opts, base_dir: str, config_from_latest: bool) -> List[str]:
    if opts.cli_from_latest:
        tag = latest_tag(opts, base_dir)
        if not tag:
            return []
        torev = opts.to if opts.to else 'HEAD'
        if resolve_rev(torev, opts, base_dir) is None:
            return []
        return git_rev_list([f'{tag}..{torev}'], opts, base_dir)
    if opts.cli_from:
        if resolve_rev(opts.from_commit or '', opts, base_dir) is None:
            return []
        torev = opts.to if opts.to else 'HEAD'
        if resolve_rev(torev, opts, base_dir) is None:
            return []
        return git_rev_list([f'{opts.from_commit}..{torev}'], opts, base_dir)
    if config_from_latest:
        # The observed 0.10.0 binary's config-driven from-latest path yields an empty walk;
        # the CLI -F path above performs the actual latest-tag walk.
        return []
    # With no explicit starting point, --to is ignored by the original; it walks HEAD.
    if resolve_rev('HEAD', opts, base_dir) is None:
        return []
    return git_rev_list(['HEAD'], opts, base_dir)


def commit_link(full: str, opts: Opts) -> str:
    short = full[:8]
    repo = opts.repository
    if not repo:
        return short
    if opts.link_style in ('github', 'gitlab'):
        return f"{repo}/commit/{full}"
    if opts.link_style == 'stash':
        return f"{repo}/commits/{full}"
    if opts.link_style == 'cgit':
        return f"{repo}/commit/?id={full}"
    return short


def issue_link(num: Optional[int], opts: Opts) -> str:
    repo = opts.repository
    suffix = '' if num is None else str(num)
    if repo and opts.link_style in ('github', 'gitlab'):
        return f"{repo}/issues/{suffix}"
    return suffix


def parse_commit(h: str, msg: str, alias_to_section: Dict[str, int], opts: Opts) -> Optional[Tuple[int, CommitEntry]]:
    lines = msg.splitlines()
    if not lines:
        return None
    first = lines[0]
    m = re.match(r'^([^\s(:]+)(?:\(([^)]*)\))?:(.*)$', first)
    if not m:
        return None
    typ, comp, subj = m.group(1), m.group(2), m.group(3)
    if typ not in alias_to_section:
        return None
    if comp == '':
        comp = None
    closes: List[Issue] = []
    break_entries: List[Optional[int]] = []
    break_issues: List[Issue] = []
    for line in lines[1:]:
        im = re.search(r'(?:Closes|Fixes) #(\d+)', line)
        if im:
            n = int(im.group(1))
            closes.append(Issue(n, issue_link(n, opts)))
        if line.startswith('BREAKING'):
            if im:
                n = int(im.group(1))
                break_entries.append(n)
                break_issues.append(Issue(n, issue_link(n, opts)))
            else:
                break_entries.append(None)
    ce = CommitEntry(
        component=comp,
        subject=subj,
        full_hash=h,
        short_hash=h[:8],
        commit_link=commit_link(h, opts),
        closes=closes,
        break_entries=break_entries,
        break_issues=break_issues,
    )
    return alias_to_section[typ], ce


def build_sections(section_cfg: List[Tuple[str, List[str]]], hashes: List[str], opts: Opts, base_dir: str) -> List[SectionOut]:
    alias_to_section: Dict[str, int] = {}
    for idx, (_title, aliases) in enumerate(section_cfg):
        for a in aliases:
            if a not in alias_to_section:
                alias_to_section[a] = idx
    buckets: List[List[CommitEntry]] = [[] for _ in section_cfg]
    if not section_cfg:
        return []
    for h in hashes:
        msg = get_message(h, opts, base_dir)
        parsed = parse_commit(h, msg, alias_to_section, opts)
        if parsed is None:
            continue
        idx, ce = parsed
        buckets[idx].append(ce)
    out: List[SectionOut] = []
    for idx, (title, _aliases) in enumerate(section_cfg):
        commits = buckets[idx]
        if not commits:
            continue
        grouped: Dict[Optional[str], List[CommitEntry]] = {}
        order_keys: List[Optional[str]] = []
        # The original groups by component with no component first, then component names sorted.
        none_group = [c for c in commits if c.component is None]
        flat: List[CommitEntry] = []
        if none_group:
            flat.extend(none_group)
        for comp in sorted({c.component for c in commits if c.component is not None}):
            flat.extend([c for c in commits if c.component == comp])
        out.append(SectionOut(title, flat))
    return out


def markdown_issue_items(issues: List[Issue]) -> str:
    return ', '.join(f"[#{i.issue}]({i.issue_link})" for i in issues)


def markdown_break_items(c: CommitEntry, opts: Opts) -> List[str]:
    # Without repository links, the original tends to suppress a single breaking marker
    # in markdown, but it shows repeated empty markers for multiple BREAKING lines.
    if not opts.repository and len(c.break_entries) <= 1:
        return []
    items: List[str] = []
    for entry in c.break_entries:
        if entry is None:
            items.append(f"[#]({issue_link(None, opts)})")
        else:
            items.append(f"[#{entry}]({issue_link(entry, opts)})")
    return items


def markdown_suffix(c: CommitEntry, opts: Opts) -> str:
    s = f"([{c.short_hash}]({c.commit_link})"
    if c.closes:
        s += ", closes " + markdown_issue_items(c.closes)
    bitems = markdown_break_items(c, opts)
    if bitems:
        s += ", breaks " + ', '.join(bitems)
    s += ")"
    return s


def render_markdown(version: Optional[str], subtitle: Optional[str], sections: List[SectionOut], opts: Opts, today: str) -> str:
    ver = version if version is not None else ""
    sub = subtitle if subtitle is not None else ""
    s = f'<a name="{ver}"></a>\n'
    s += f'## {ver} {sub} ({today})\n'
    if not sections:
        s += "\n"
        return s
    s += "\n\n"
    for si, sec in enumerate(sections):
        s += f"#### {sec.title}\n\n"
        # sec.commits is already flattened in group order. For markdown we need to know groups.
        idx = 0
        while idx < len(sec.commits):
            comp = sec.commits[idx].component
            group = []
            while idx < len(sec.commits) and sec.commits[idx].component == comp:
                group.append(sec.commits[idx])
                idx += 1
            if comp is None:
                for c in group:
                    s += f"*  {c.subject} {markdown_suffix(c, opts)}\n"
            else:
                if len(group) == 1:
                    c = group[0]
                    s += f"* **{comp}:** {c.subject} {markdown_suffix(c, opts)}\n"
                else:
                    s += f"* **{comp}:**\n"
                    for c in group:
                        s += f"  * {c.subject} {markdown_suffix(c, opts)}\n"
        if si != len(sections) - 1:
            s += "\n"
    return s


def json_string(x: str) -> str:
    return json.dumps(x, ensure_ascii=False, separators=(',', ':'))


def render_json(version: Optional[str], subtitle: Optional[str], sections: List[SectionOut], opts: Opts, today: str) -> str:
    if version is None:
        verpart = "None"
    else:
        verpart = "Some(" + json_string(version) + ")"
    subpart = "null" if subtitle is None else subtitle
    s = '{"header":{"version":' + verpart + ',"patch_version":false,"subtitle":' + subpart + ',"date":' + json_string(today) + '},"sections":'
    if not sections:
        return s + 'null}'
    sec_parts = []
    for sec in sections:
        commit_parts = []
        for c in sec.commits:
            comp = 'null' if c.component is None else json_string(c.component)
            closes = 'null'
            if c.closes:
                closes = '[' + ','.join('{"issue":' + str(i.issue) + ',"issue_link":' + json_string(i.issue_link) + '}' for i in c.closes) + ']'
            if not c.break_entries:
                breaks = 'null'
            elif c.break_issues:
                breaks = '[' + ','.join('{"issue":' + str(i.issue) + ',"issue_link":' + json_string(i.issue_link) + '}' for i in c.break_issues) + ']'
            else:
                breaks = '[]'
            commit_parts.append(
                '{"component":' + comp +
                ',"subject":' + json_string(c.subject) +
                ',"commit_link":' + json_string(c.commit_link) +
                ',"closes":' + closes +
                ',"breaks":' + breaks + '}'
            )
        sec_parts.append('{"title":' + json_string(sec.title) + ',"commits":[' + ','.join(commit_parts) + ']}')
    return s + '[' + ','.join(sec_parts) + ']}'


def read_file_if_exists(path: str) -> str:
    try:
        with open(path, 'r', encoding='utf-8') as f:
            return f.read()
    except Exception:
        return ''


def main(argv: List[str]) -> int:
    start = time.time()
    try:
        opts = parse_args(argv)
        # Configuration is mandatory as a readable TOML file, even if most [clog]
        # values are not used by the observed binary.
        config_path = opts.config
        if not os.path.isabs(config_path):
            config_path = os.path.abspath(config_path)
        sections_cfg, config_from_latest = parse_toml(config_path)
        if (opts.major or opts.minor or opts.patch) and opts.setversion is None:
            app_error("Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format.")
        base_dir = infer_base_dir(opts, config_path)
        hashes = collect_hashes(opts, base_dir, config_from_latest)
        sections = build_sections(sections_cfg, hashes, opts, base_dir)
        today = date.today().isoformat()
        version = opts.setversion if opts.setversion is not None else None
        if opts.format == 'json':
            content = render_json(version, opts.subtitle, sections, opts, today)
        else:
            content = render_markdown(version, opts.subtitle, sections, opts, today)
        dest = opts.changelog or opts.outfile
        old = ''
        if opts.infile:
            old = read_file_if_exists(opts.infile)
        elif dest:
            old = read_file_if_exists(dest)
        final_content = content
        if opts.infile or dest:
            final_content = content + "\n\n\n" + old
        if dest:
            try:
                with open(dest, 'w', encoding='utf-8') as f:
                    f.write(final_content)
            except Exception:
                app_error("fatal I/O error with output file")
        else:
            sys.stdout.write(final_content)
        elapsed_ms = int((time.time() - start) * 1000)
        sys.stdout.write(f"changelog written. (took {elapsed_ms} ms)\n")
        return 0
    except CliExit as e:
        return e.code


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
